-- Seed tool classifications for registry-backed connectors
-- Generated by scripts/classify-connector-tools.ts --backfill-all --from-registry
-- Connectors: linear, atlassian_jira, atlassian_confluence, bamboohr, cal_com,
--             snowflake, mailchimp, sendgrid, asana, trello, woocommerce

-- linear (8 tools)
ON CONFLICT (tool_name, COALESCE(tenant_id, '__global__')) DO UPDATE
  SET categories             = EXCLUDED.categories,
      tool_description_hash  = EXCLUDED.tool_description_hash,
      reviewed_by            = EXCLUDED.reviewed_by,
      classified_at          = NOW();

